#!/usr/bin/env python3
"""Parse a CSV file, extract nested columns, and output a Markdown table.

Nested columns are detected in two ways:
1. Column headers with dot notation (e.g. "user.name", "user.address.city")
2. Cell values containing JSON objects/arrays

Usage:
    python csv_to_markdown.py input.csv [--columns col1,col2] [--flatten]
"""

import argparse
import csv
import json
import sys


def flatten_dict(d, parent_key="", sep="."):
    """Flatten a nested dict into dot-notation keys."""
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep).items())
        elif isinstance(v, list):
            items.append((new_key, json.dumps(v)))
        else:
            items.append((new_key, v))
    return dict(items)


def parse_json_cell(value):
    """Try to parse a cell value as JSON; return None if it fails."""
    stripped = value.strip()
    if stripped.startswith("{") or stripped.startswith("["):
        try:
            return json.loads(stripped)
        except json.JSONDecodeError:
            return None
    return None


def expand_nested_columns(rows, headers):
    """Expand rows where dot-notation headers imply nested structure.

    Returns new headers and rows with nested columns flattened.
    """
    expanded_headers = list(headers)
    expanded_rows = []

    for row in rows:
        new_row = {}
        for header in headers:
            value = row.get(header, "")
            # Check if the cell contains JSON
            parsed = parse_json_cell(value)
            if isinstance(parsed, dict):
                flat = flatten_dict(parsed)
                for k, v in flat.items():
                    col = f"{header}.{k}"
                    if col not in expanded_headers:
                        expanded_headers.append(col)
                    new_row[col] = str(v) if v is not None else ""
            elif isinstance(parsed, list):
                new_row[header] = json.dumps(parsed)
            else:
                new_row[header] = value
        expanded_rows.append(new_row)

    return expanded_headers, expanded_rows


def select_columns(headers, rows, columns):
    """Keep only the specified columns, preserving order."""
    selected = [c for c in columns if c in headers]
    new_rows = [{c: row.get(c, "") for c in selected} for row in rows]
    return selected, new_rows


def to_markdown(headers, rows):
    """Render headers and rows as a Markdown table."""
    if not headers:
        return ""

    # Calculate column widths
    widths = {h: len(h) for h in headers}
    for row in rows:
        for h in headers:
            widths[h] = max(widths[h], len(row.get(h, "")))

    # Header row
    header_line = "| " + " | ".join(h.ljust(widths[h]) for h in headers) + " |"
    separator = "| " + " | ".join("-" * widths[h] for h in headers) + " |"

    # Data rows
    data_lines = []
    for row in rows:
        line = "| " + " | ".join(row.get(h, "").ljust(widths[h]) for h in headers) + " |"
        data_lines.append(line)

    return "\n".join([header_line, separator] + data_lines)


def main():
    parser = argparse.ArgumentParser(description="Parse CSV with nested columns to Markdown.")
    parser.add_argument("csv_file", help="Path to the CSV file (use - for stdin)")
    parser.add_argument("--columns", help="Comma-separated list of columns to include")
    parser.add_argument("--flatten", action="store_true", help="Flatten JSON cell values into dot-notation columns")
    parser.add_argument("--limit", type=int, default=0, help="Max rows to output (0 = all)")
    args = parser.parse_args()

    # Read CSV
    if args.csv_file == "-":
        reader = csv.DictReader(sys.stdin)
    else:
        f = open(args.csv_file, newline="", encoding="utf-8")
        reader = csv.DictReader(f)

    headers = reader.fieldnames or []
    rows = [dict(row) for row in reader]

    if args.csv_file != "-":
        f.close()

    if not headers:
        print("Error: CSV has no headers.", file=sys.stderr)
        sys.exit(1)

    # Expand nested columns if requested
    if args.flatten:
        headers, rows = expand_nested_columns(rows, headers)

    # Filter columns
    if args.columns:
        col_list = [c.strip() for c in args.columns.split(",")]
        headers, rows = select_columns(headers, rows, col_list)

    # Limit rows
    if args.limit > 0:
        rows = rows[:args.limit]

    # Output
    print(to_markdown(headers, rows))


if __name__ == "__main__":
    main()
